    g.text([a / 2, a / 2], "a²", 0, 4).text([a + b / 2, a / 2], "ab", 0, 4).text([a / 2, a + b / 2], "ab", 0, 4).text([a + b / 2, a + b / 2], "b²", 0, 4);
    g.side([0, 0], [a, 0], "a").side([a, 0], [a + b, 0], "b");
    return g.svg("(a + b)² = a² + 2ab + b²");
